    dict(id='D43', title='엑셀 날짜', decision='공정 시작 시각으로 고정(v1 경합 LOG-058 없앰). Arc 경고는 웹훅 대신 이벤트 → 포털.', reason="2단계 기록 출력 작성 중 판단(v1 실행 골든 바이트 동일)", confirm=True, where="v2/ch12/outputs"),
